# Manually verify box locations in test input
test_input_lines = test_input
h, w = len(test_input), len(test_input[0])

print(f"Test input dimensions: {h}x{w}")
print("\nSearching for hollow boxes in test input:")

# Look for corners of boxes - a corner has the border color and potentially a different interior
found = []
for r in range(h):
    for c in range(w):
        color = test_input[r][c]
        # Check if this could be top-left corner of a valid box
        # Must have different interior inside
        if c + 2 >= w or r + 2 >= h:
            continue

        interior = test_input[r+1][c+1]
        if interior == color:
            continue

        # Check if this forms a valid box (min 3x3)
        margin = 0

        # Find box extent along row
        for dc in range(1, 8):
            if c + dc >= w:
                break
            if test_input[r][c+dc] == color:
                margin = max(margin, dc)
            else:
                break

        # Find box extent along col
        for dr in range(1, 8):
            if r + dr >= h:
                break
            if test_input[r+dr][c] == color:
                margin = max(margin, dr)
            else:
                break

        if margin < 1:
            continue

        box_size_h = margin * 2  # Top and bottom
        box_size_w = margin * 2  # Left and right

        if box_size_h < 3 or box_size_w < 3:
            continue

        # Verify this is a valid box
        is_valid = True

        # Check borders
        for dc in range(box_size_w):
            if test_input[r][c+dc] != color:
                is_valid = False
                break

        if not is_valid:
            for dc in range(box_size_w):
                if test_input[r+box_size_h-1][c+dc] != color:
                    is_valid = False
                    break

        if not is_valid:
            for dr in range(1, box_size_h-1):
                if test_input[r+dr][c] != color or test_input[r+dr][c+box_size_w-1] != color:
                    is_valid = False
                    break

        if not is_valid:
            continue

        # Check interior is uniform
        interior = test_input[r+1][c+1]
        for dr in range(1, box_size_h-1):
            for dc in range(1, box_size_w-1):
                if test_input[r+dr][c+dc] != interior:
                    is_valid = False
                    break
            if not is_valid:
                break

        if is_valid and box_size_h >= 3 and box_size_w >= 3:
            found.append({
                'box_num': len(found),
                'border': color,
                'interior': interior,
                'top': r,
                'bottom': r + box_size_h - 1,
                'left': c,
                'right': c + box_size_w - 1,
                'size_h': box_size_h,
                'size_w': box_size_w
            })
            print(f"\nFound box #{len(found)}:")
            print(f"  Border color: {color}")
            print(f"  Interior: {interior}")
            print(f"  Rows: {r} to {r+box_size_h-1}")
            print(f"  Cols: {c} to {c+box_size_w-1}")
            print(f"  Size: {box_size_h}x{box_size_w}")

print("\n\nSummary of boxes in test input:")
for b in found:
    print(f"{b['border']} box at ({b['left']},{b['top']}) {b['size_h']}x{b['size_w']}, interior={b['interior']}")

